mapper.select:
SELECT COUNT(1)
FROM ultary_user
WHERE (
	nickname = #{nickname}
	OR (
		previous_nickname = #{nickname}
		AND nickname_changed_at > DATE_SUB(NOW(), INTERVAL #{reserveDays} DAY)
	)
)

	AND user_no != #{excludeUserNo}

SELECT COUNT(1)
FROM ultary_user
WHERE email = #{email}

	AND user_no != #{excludeUserNo}

		SELECT 
		FROM ultary_user u
		WHERE u.withdrawal_status = 'ACTIVE'
		  AND u.user_no != #{viewerUserNo}
		  AND (LOCATE(LOWER(#{q}), LOWER(u.nickname)) > 0 OR EXISTS (
            SELECT 1 FROM ultary_pet sp WHERE sp.user_no=u.user_no AND sp.is_deleted=0
            AND LOCATE(LOWER(#{q}), LOWER(sp.name)) > 0
          ))
		  AND NOT EXISTS (
			SELECT 1
			FROM ultary_user_block b
			WHERE b.is_deleted = 0
			  AND (
				b.blocker_user_no = u.user_no AND b.blocked_user_no = #{viewerUserNo}
			  )
		  )
		ORDER BY u.user_no DESC
		LIMIT #{limit}

		SELECT 
		FROM ultary_user u
		WHERE u.withdrawal_status = 'ACTIVE'
		  AND u.user_no != #{viewerUserNo}
		  AND (LOCATE(LOWER(#{q}), LOWER(u.nickname)) > 0 OR EXISTS (
            SELECT 1 FROM ultary_pet sp WHERE sp.user_no=u.user_no AND sp.is_deleted=0
            AND LOCATE(LOWER(#{q}), LOWER(sp.name)) > 0
          ))
		  AND NOT EXISTS (
			SELECT 1
			FROM ultary_user_block b
			WHERE b.is_deleted = 0
			  AND (
				b.blocker_user_no = u.user_no AND b.blocked_user_no = #{viewerUserNo}
			  )
		  )
		ORDER BY u.user_no DESC
		LIMIT #{limit}

